//! The DESK domain-class registry, embedded as data.
//!
//! `data/desk_domains.json` is generated by `scripts/gen-desk-domains.sh` from the owner's DESK
//! library (`library/pcb_domains`, MIT; Python reference, re-implemented here). It holds every
//! DESK archetype ("domain class"): name, description, classification keywords and features,
//! required component roles, constraints, verification requirements, standards and the DESK
//! maturity label. EAK never claims more for a class than its DESK label allows (see
//! [`Maturity::ceiling`]).

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const DATA: &str = include_str!("../../data/desk_domains.json");

/// DESK evidence state (`docs/domain_intelligence/EVIDENCE_AND_MATURITY_POLICY.md`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Maturity {
    Draft,
    Advisory,
    Implemented,
    OfflineTested,
    VerifiedAgainstSource,
    LiveVerified,
    NeedsHardwareValidation,
    Blocked,
}

/// What EAK may say about guidance carrying a given DESK label. This is a ceiling, not a score:
/// EAK adds no evidence of its own, so a class is never presented as more mature than DESK says.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Ceiling {
    pub label: Maturity,
    /// Short, UI-ready statement of what the guidance is.
    pub claim: &'static str,
    /// Guidance may be shown as a requirement (never true below human verification).
    pub may_present_as_requirement: bool,
    /// Guidance may be shown at all (false only for `BLOCKED`, known wrong or unsafe).
    pub may_show_guidance: bool,
}

impl Maturity {
    pub fn ceiling(self) -> Ceiling {
        let (claim, requirement, show) = match self {
            Maturity::Draft => (
                "Draft: written but never exercised. Review prompts only, not requirements.",
                false,
                true,
            ),
            Maturity::Advisory => (
                "Advisory: a deliberate review item with no deterministic evaluator.",
                false,
                true,
            ),
            Maturity::Implemented => (
                "Implemented in DESK without a proving test. Not verified against any standard.",
                false,
                true,
            ),
            Maturity::OfflineTested => (
                "Offline-tested in DESK fixtures. Not verified against the cited standards and not validated on hardware.",
                false,
                true,
            ),
            Maturity::VerifiedAgainstSource => (
                "A human compared the values with the cited source. Not validated on hardware.",
                true,
                true,
            ),
            Maturity::LiveVerified => (
                "Confirmed by a human on a real board or live ECAD run in DESK.",
                true,
                true,
            ),
            Maturity::NeedsHardwareValidation => (
                "Offline evidence exists; hardware validation is required before trust.",
                false,
                true,
            ),
            Maturity::Blocked => (
                "Blocked: known wrong or unsafe in DESK. Must not be applied.",
                false,
                false,
            ),
        };
        Ceiling {
            label: self,
            claim,
            may_present_as_requirement: requirement,
            may_show_guidance: show,
        }
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct Domain {
    pub domain_id: String,
    pub name: String,
    pub description: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Overlay {
    pub overlay_id: String,
    pub name: String,
    pub applies_when: Value,
    #[serde(default)]
    pub adds_component_families: Vec<String>,
    #[serde(default)]
    pub precedence: i64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MaturityRecord {
    pub status: Maturity,
    #[serde(default)]
    pub evidence: String,
    #[serde(default)]
    pub rule_ids: Vec<String>,
}

#[derive(Debug, Clone, Deserialize, Default)]
pub struct ClassificationSpec {
    #[serde(default)]
    pub keywords: BTreeMap<String, f64>,
    #[serde(default)]
    pub features: BTreeMap<String, Value>,
}

/// One DESK domain class.
#[derive(Debug, Clone, Deserialize)]
pub struct Archetype {
    pub archetype_id: String,
    pub name: String,
    pub domain: String,
    pub description: String,
    #[serde(default)]
    pub intended_applications: Vec<String>,
    #[serde(default)]
    pub typical_overlays: Vec<String>,
    #[serde(default)]
    pub required_component_roles: Vec<String>,
    #[serde(default)]
    pub typical_component_families: Vec<String>,
    #[serde(default)]
    pub critical_electrical_constraints: Vec<String>,
    #[serde(default)]
    pub verification_requirements: Vec<String>,
    #[serde(default)]
    pub applicable_standards: Vec<String>,
    #[serde(default)]
    pub unsupported_conditions: Vec<String>,
    #[serde(default)]
    pub classification: ClassificationSpec,
    pub maturity: MaturityRecord,
}

#[derive(Debug, Deserialize)]
pub struct Registry {
    pub source: String,
    pub schema_version: String,
    pub generated: String,
    pub domains: Vec<Domain>,
    pub overlays: Vec<Overlay>,
    pub archetypes: Vec<Archetype>,
}

impl Registry {
    pub fn archetype(&self, id: &str) -> Option<&Archetype> {
        self.archetypes.iter().find(|a| a.archetype_id == id)
    }
    pub fn domain(&self, id: &str) -> Option<&Domain> {
        self.domains.iter().find(|d| d.domain_id == id)
    }
    pub fn overlay(&self, id: &str) -> Option<&Overlay> {
        self.overlays.iter().find(|o| o.overlay_id == id)
    }
}

/// The embedded registry. The data is part of the binary and validated by the tests, so a
/// parse failure is a build defect, not a runtime condition.
pub fn registry() -> &'static Registry {
    static R: OnceLock<Registry> = OnceLock::new();
    R.get_or_init(|| {
        serde_json::from_str(DATA).expect("embedded desk_domains.json is generated and validated")
    })
}
